  const setActionLoading = (key: string, loading: boolean) => {
    setLoadingActions(prev => ({ ...prev, [key]: loading }));
  };

  const handleSyncHireScoreLive = async () => {
    setIsSyncingHireScore(true);
    try {
      const res = await fetch(`/api/hirescore?college_id=${encodeURIComponent(activeCollegeId || "")}`, {
        method: "POST"
      });
      const data = await res.json();
      if (data.success) {
        toast(`Synced ${data.syncedCount} student(s) with live HireScore & EFSET benchmark data!`, "success");
        await refreshData();
      } else {
        toast(data.message || "Failed to sync HireScore data.", "error");
      }
    } catch (err: any) {
      toast("Error syncing HireScore: " + err.message, "error");
    } finally {
      setIsSyncingHireScore(false);
    }
  };

  const handleSingleDeleteStudent = async (st: any) => {
    if (!st || !st.id) return;
    const ok = await showConfirm({
      title: "Delete Student Record",
      message: `Are you sure you want to delete ${st.name} (${st.roll_number || st.id})? This will permanently remove their profile, attendance logs, and login credentials.`,
      confirmLabel: "Delete Record",
      danger: true
    });
    if (ok) {
      setActionLoading(`delete_student_${st.id}`, true);
      try {
        const res = await deleteStudent(st.id);
        if (res.success) {
          toast(`Student ${st.name} deleted successfully.`, "success");
          setSelectedStudentIds(prev => prev.filter(id => id !== st.id));
          if (selectedStudentForDetail?.id === st.id) {
            setSelectedStudentForDetail(null);
          }
        } else {
          toast(res.message || "Failed to delete student.", "error");
        }
      } finally {
        setActionLoading(`delete_student_${st.id}`, false);
      }
    }
  };

  const bulk = useBulkOperation();
  const handleBulkDeleteStudents = async (targetIds?: string[]) => {
    const idsToDelete = [...new Set(targetIds || selectedStudentIds)];
    if (idsToDelete.length > 500) {
      toast("Select at most 500 students or narrow your filters before deleting.", "warning");
      return;
    }
    if (!idsToDelete || idsToDelete.length === 0) return;
    const ok = await showConfirm({
      title: targetIds ? "Delete All Filtered Students" : "Delete Selected Students",
      message: `Permanently delete ${idsToDelete.length} students and their linked attendance, marks, fees, interviews and login accounts? This cannot be undone.`,
      confirmLabel: `Delete ${idsToDelete.length} Students`,
      danger: true
    });
    if (ok && bulk.begin({ title: 'Delete students', campus: activeCollegeName, danger: true, detail: `Deleting ${idsToDelete.length} students and their linked records.` })) {
      setActionLoading('bulk_delete_students', true);
      try {
        const res = await bulkDeleteStudents(idsToDelete);
        if (res.success) {
          bulk.finish(res.message);
          setSelectedStudentIds(prev => prev.filter(id => !idsToDelete.includes(id)));
          if (selectedStudentForDetail && idsToDelete.includes(selectedStudentForDetail.id)) {
            setSelectedStudentForDetail(null);
          }
        } else {
          bulk.finish(res.message || "Deletion could not be confirmed. Refresh before retrying.", true);
        }
      } finally {
        setActionLoading('bulk_delete_students', false);
      }
    }
  };

  // ── CAM Academic Tracker Filters ──
  const [camAcadDeptFilter, setCamAcadDeptFilter] = useState<string>("all");
  const [camAcadCohortFilter, setCamAcadCohortFilter] = useState<string>("all");
  const [camAcadSemFilter, setCamAcadSemFilter] = useState<string>("all");
  const [camAcadMentorFilter, setCamAcadMentorFilter] = useState<string>("all");
  const [camAcadSubjectFilter, setCamAcadSubjectFilter] = useState<string>("all");
  const [camAcadUnitFilter, setCamAcadUnitFilter] = useState<string>("all");
  const [camAcadStartDate, setCamAcadStartDate] = useState<string>(() => shiftDateStr(getLocalDateStr(), -7));
  const [camAcadEndDate, setCamAcadEndDate] = useState<string>(() => getLocalDateStr());
  const [camAcadSearch, setCamAcadSearch] = useState<string>("");
  const [camAcadPage, setCamAcadPage] = useState<number>(1);
  const [camAcadPageSize, setCamAcadPageSize] = useState<number>(20);
  const [camAcadSubTab, setCamAcadSubTab] = useState<"weekly_tasks" | "lesson_conduction">("weekly_tasks");
  const [camAcadWeeklyDept, setCamAcadWeeklyDept] = useState<string>("");
