  const handleSaveYear = async (index: number) => {
    if (!editingYearValue.trim()) return;
    const oldYear = academicYears[index];
    const newYear = editingYearValue.trim();
    if (newYear === oldYear) {
      setEditingYearIndex(null);
      return;
    }
    const ok = await showConfirm({
      title: "Rename Academic Year",
      message: `Replace "${oldYear}" with "${newYear}"? The old year definition is removed and recreated under the new name.`,
      confirmLabel: "Rename"
    });
    if (!ok) return;
    // Create the new year before deleting the old one so a failed save never leaves no year behind.
    const res = await saveAcademicYear(newYear);
    if (!res.success) {
      toast(res.message || "Failed to update academic year", "error");
      return;
    }
    const del = await deleteAcademicYear(oldYear);
    if (!del.success) {
      toast(`"${newYear}" saved, but "${oldYear}" could not be removed: ${del.message || "delete failed"}`, "error");
    } else {
      toast("Academic year updated successfully.", "success");
    }
    setEditingYearIndex(null);
  };

