  const handleSaveRichEventSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!evFormName.trim() || !evFormDate) {
      toast("Event Title and Start Date are required.", "error");
      return;
    }

    const finalCategory = (isCustomCategory || evFormCategory === "custom")
      ? (evFormCustomCategory.trim() || "Campus Fest")
      : evFormCategory;

    const payload = {
      id: editingEventObj ? editingEventObj.id : undefined,
      name: evFormName.trim(),
      date: evFormDate,
      end_date: evFormEndDate || null,
      category: finalCategory,
      department: evFormDept,
      audience: evFormAudience,
      status: evFormStatus,
      venue: evFormVenue || null,
      desc: evFormDesc || null,
      coordinator: evFormCoordinator || null,
      chief_guest: evFormChiefGuest || null,
      registration_link: evFormRegistrationLink || null,
      photos: evFormPhotos.length > 0 ? JSON.stringify(evFormPhotos) : null,
      college_id: activeCollegeId
    };

    setIsSubmittingEvent(true);
    try {
      const res = await saveAcademicEvent(payload);
      if (res.success) {
        const synced = res.dayOrderSync?.synced || [];
        const protectedDates = res.dayOrderSync?.protectedDates || [];
        const action = editingEventObj ? "updated" : "created";
        if (synced.length > 0) {
          toast(
            `Campus event ${action}. Day Order set to Event for ${synced.map((s: any) => `${s.dateStr} (${s.day_order})`).join(", ")}.`,
            "success"
          );
        } else if (res.dayOrderSync?.skipped) {
          toast(`Campus event ${action}. Open a specific campus to sync its Day Order.`, "warning");
        } else if (protectedDates.length > 0) {
          toast(`Campus event ${action}. Day Order left as Holiday/Exam for ${protectedDates.join(", ")}.`, "warning");
        } else {
          toast(`Campus event ${action}.`, "success");
        }
        setShowEventModal(false);
        if (synced.length > 0) await fetchDailyConfigs();
      } else {
        toast(res.message || "Failed to save event", "error");
      }
    } catch (err: any) {
      toast("Error saving event: " + (err?.message || "Unknown error"), "error");
    } finally {
      setIsSubmittingEvent(false);
    }
  };

